///   4. WebForms event handlers     → MVC action methods returning IActionResult
///   5. Response.Write/Clear/AddHeader → FileContentResult or direct Response writes
/// </summary>
public class ReportController : Controller
{
    // --- Pattern 1: File export (was Response.End) ---
    //
    // Before: Response.Clear/Write/End threw ThreadAbortException to halt the
    //         pipeline. In ASP.NET Core, returning a result naturally ends the
    //         response — no abort needed.
    [HttpPost]
    public IActionResult Export()
    {
        var data = GenerateReport();

        // Return a FileContentResult — the framework handles headers and
        // streaming. No Response.Clear/End equivalent is needed.
        return File(
            System.Text.Encoding.UTF8.GetBytes(data),
            "text/csv",
            "report.csv");
    }

    // --- Pattern 2: Conditional redirect (was Response.Redirect(url, true)) ---
    //
    // Before: Response.Redirect(url, true) called Thread.Abort internally,
    //         which required catching ThreadAbortException to prevent crashes.
    //         In ASP.NET Core, returning RedirectResult ends the action cleanly.
    [HttpPost]
    public IActionResult ProcessAndRedirect()
    {
        if (!User.Identity?.IsAuthenticated ?? true)
        {
            // Just return — no Thread.Abort, no endResponse parameter.
            return Redirect("/login");
        }

        try
        {
            ProcessRequest();
            return Redirect("/success");
        }
        // ThreadAbortException catch block removed — it is never thrown in
        // .NET 8 (Thread.Abort throws PlatformNotSupportedException).
        catch (Exception ex)
        {
            LogError(ex);
            return Redirect("/error");
        }
    }

    // --- Long-running export with cancellation support ---
    //
    // Bonus: ASP.NET Core provides HttpContext.RequestAborted to detect when
    // the client disconnects. Use it for expensive report generation.
    [HttpPost]
    public async Task<IActionResult> ExportLargeReport(CancellationToken cancellationToken)
    {
        // ASP.NET Core automatically binds HttpContext.RequestAborted here.
        // If the client disconnects, the token fires cooperatively — no
        // Thread.Abort needed.
        var data = await GenerateReportAsync(cancellationToken);

        return File(
            System.Text.Encoding.UTF8.GetBytes(data),
            "text/csv",
            "report.csv");
    }

    private string GenerateReport() => "col1,col2\nval1,val2";

    private async Task<string> GenerateReportAsync(CancellationToken token)
    {
        // Check the token at regular intervals in expensive work
        await Task.Delay(100, token); // placeholder for real work
        token.ThrowIfCancellationRequested();
        return "col1,col2\nval1,val2";
    }

    private void ProcessRequest() { /* business logic */ }

    private void LogError(Exception ex) { /* logging */ }
}
